// ── LLM-as-judge (optional, --judge=llm) ─────────────────────────────────────
// Scores the six rubric dimensions with Groq. Use only when you want a
// qualitative second opinion; the RULE judge remains the reproducible default.
//
// SELF-PREFERENCE CAVEAT: the answers under test are generated by the same model
// family (and possibly the same model) that judges here. LLM judges are known to
// favor outputs in their own style/family, so this verdict can be biased upward.
// Treat it as advisory; the deterministic checks + rule judge are the gate.

import type { ParsedReply } from "../../postprocess";
import { CHAT_CONFIG } from "../../config";
import { DIMENSIONS, verdictFromScores } from "../rubric";
import type {
  DimensionName,
  DimensionScore,
  Expectation,
  JudgeVerdict,
} from "../types";

const GROQ_URL = "https://api.groq.com/openai/v1/chat/completions";

interface RawVerdict {
  [dim: string]: { score: number; pass: boolean; reason: string };
}

function buildJudgePrompt(parsed: ParsedReply, exp: Expectation, prompt: string) {
  const rubric = DIMENSIONS.map(
    (d) => `- ${d.name} (threshold ${d.threshold}): ${d.description}`
  ).join("\n");

  return `You are a strict evaluator of a portfolio chat answer written in the first
person as the engineer Rudra. Score each rubric dimension from 0.0 to 1.0.

RUBRIC:
${rubric}

USER ASKED: ${JSON.stringify(prompt)}

EXPECTATION: ${JSON.stringify(exp)}

THE ANSWER (rendered prose only; cards shown as [card:<kind>]):
${parsed.text || "(no prose)"}
CARDS: ${parsed.actions.map((a) => a.type).join(", ") || "none"}
SUGGESTIONS: ${parsed.next.join(" | ") || "none"}

Respond with ONLY a JSON object, no prose, of the exact shape:
{${DIMENSIONS.map((d) => `"${d.name}":{"score":0.0,"pass":true,"reason":"..."}`).join(",")}}`;
}

export async function llmJudge(
  parsed: ParsedReply,
  exp: Expectation,
  prompt: string
): Promise<JudgeVerdict> {
  const key = process.env.GROQ_API_KEY;
  if (!key) {
    throw new Error("GROQ_API_KEY is not set; --judge=llm needs it.");
  }

  const res = await fetch(GROQ_URL, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${key}`,
    },
    body: JSON.stringify({
      model: CHAT_CONFIG.model,
      messages: [
        {
          role: "system",
          content:
            "You are a precise grader. Output strict JSON only. No markdown, no commentary.",
        },
        { role: "user", content: buildJudgePrompt(parsed, exp, prompt) },
      ],
      temperature: 0,
      top_p: 1,
      max_tokens: 700,
      stream: false,
      response_format: { type: "json_object" },
    }),
  });

  if (!res.ok) {
    const detail = await res.text().catch(() => "");
    throw new Error(`LLM judge Groq error ${res.status}: ${detail.slice(0, 200)}`);
  }

  const json = (await res.json()) as {
    choices?: { message?: { content?: string } }[];
  };
  const content = json.choices?.[0]?.message?.content ?? "{}";

  let raw: RawVerdict;
  try {
    raw = JSON.parse(content) as RawVerdict;
  } catch {
    throw new Error(`LLM judge returned non-JSON: ${content.slice(0, 200)}`);
  }

  const scores: DimensionScore[] = DIMENSIONS.map((d) => {
    const r = raw[d.name];
    const value = typeof r?.score === "number" ? Math.max(0, Math.min(1, r.score)) : 0;
    return {
      dimension: d.name as DimensionName,
      score: value,
      pass: value >= d.threshold,
      reason: typeof r?.reason === "string" ? r.reason : "(no reason)",
    };
  });

  return verdictFromScores(scores, "llm");
}
